"""Direct test for OSS upload functionality without server."""

import asyncio
import io
import oss2
import time
from deerflow.config.app_config import get_app_config

async def test_oss_connection():
    """Test OSS connection and upload directly."""
    print("="*60)
    print("Testing OSS Connection and Upload")
    print("="*60)
    
    # 加载配置
    config = get_app_config().oss
    
    print(f"Endpoint: {config.endpoint}")
